# Independent actual retail claims and genuinely earlier cure/redefault training.
if(!exists('estimate_open_workout_lgd'))library(creditratingsystem)
run_retail_workout_cases<-function(data=NULL,verify_reference=TRUE){
 if(is.null(data))data<-jsonlite::fromJSON(system.file('extdata/retail_workout_cases.json',package='creditratingsystem'),simplifyVector=FALSE)
 tr<-data$cure_training;training_end<-as.Date(tr$calendar_origin)+max(vapply(tr$rows,function(r)r$stop,numeric(1)));if(training_end>as.Date(tr$observation_end)||tr$observation_end>tr$training$known_at)stop('Cure model training spells require complete prior calendar support')
 fitted<-estimate_multistate_transitions(tr$rows,states=c('D','C'),allowed_transitions=list(c('D','C'),c('C','D')),initial_state='D',target=tr$target,training=tr$training,model_id='retail-prior-cure',model_version='1');model<-fitted$model;model$collections_contract<-list(cure_states=list('C'),default_states=list('D'),supported_actions=list('baseline'),supported_initial_states=list('D','C'),action_interpretation='observational_conditioning');out<-list()
 for(product in names(data$cases)){
  case<-data$cases[[product]];ead<-case$ead;eid<-case$episode$episode_id;date<-case$default_date
  defaults<-list(list(episode_id=eid,entity_id=case$subject_id,default_at=date,known_at=date,ead=ead,currency='EUR'));flows<-lapply(case$cashflows,function(f)list(cashflow_id=f$cashflow_id,episode_id=eid,cashflow_at=f$cashflow_date,known_at=f$known_at,amount=f$amount,kind=if(f$kind=='RECOVERY')'recovery'else'cost',currency=f$currency));linked<-build_recovery_episodes(defaults,flows,cures=list(),evaluation_cutoff='2024-03-15')$value
  final<-discount_recoveries(case$cashflows,case$discount_curve,case$fx_contract,default_date=date,evaluation_cutoff='2024-05-01',reporting_currency='EUR');known<-discount_recoveries(case$cashflows,case$discount_curve,case$fx_contract,default_date=date,evaluation_cutoff='2024-03-15',reporting_currency='EUR')
  resolved<-all(vapply(case$episode[c('resolution_date','resolution_known_at')],function(x)is.character(x)&&length(x)==1L&&x<='2024-05-01',logical(1)))
  closed<-workout_lgd(ead,final,episode_status=if(resolved)'CLOSED'else'OPEN',default_date=date,evaluation_cutoff='2024-05-01',currency='EUR')$value;incomplete<-workout_lgd(ead,known,episode_status='OPEN',default_date=date,evaluation_cutoff='2024-03-15',currency='EUR')$value
  openargs<-list(episodes=list(case$episode),cashflows=case$cashflows,fitted_recovery_model=data$residual_model,X=matrix(numeric(),1,0),valuation_contracts=list(case$valuation),future_cost_cashflows=case$future_costs,feature_order=character(),expected_target=data$target,stage_spec=data$stage_spec,as_of='2024-03-15',currency='EUR',extrapolation='parametric');estimated<-do.call(estimate_open_workout_lgd,openargs)$value;unknown<-openargs;unknown$valuation_contracts[[1]]['tail_discount_factor']<-list(NULL);unknown$valuation_contracts[[1]]['tail_assumption_reference']<-list(NULL);unidentified<-do.call(estimate_open_workout_lgd,unknown)$value
  loss<-if(!resolved)NULL else event_conditioned_loss(list(list(state_id='survival',events=list(default=FALSE),probability=.9,conditional_loss=0),list(state_id='default',events=list(default=TRUE),probability=.1,conditional_loss=closed$economic_loss)),event_names='default',currency='EUR',probability_measure='PHYSICAL')$value
  allocation<-do.call(simulate_recovery_waterfall,case$claim_allocation)$value
  history<-do.call(build_collections_episodes,case$collections_input)$value;vargs<-case$collections_value;vargs$discount_factors<-unlist(vargs$discount_factors);vargs$period_end_dates<-unlist(vargs$period_end_dates);value<-do.call(expected_collections_value,vargs)$value
  assumptions<-case$cure_recovery_assumptions;cure<-predict_cure_and_redefault(current_episode=list(episode_id=eid,state='D',model_time=0,known_at=date,ever_default=TRUE),model=model,action_conditions=assumptions[c('action_id','assumption_reference')],horizon_grid=c(0,30,60),state_recoveries=rbind(c(0,0),c(0,assumptions$recovery_on_cure),c(0,0)),target=tr$target,currency='EUR')$value
  out[[product]]<-list(mechanism=case$mechanism,claim_cost_scope=case$claim_cost_scope,claim_allocation=allocation,linked_known_cashflows=linked,discounted_recovery=final$value,closed_workout=closed,incomplete_workout=incomplete,estimated_open_workout=estimated,unidentified_tail=unidentified,event_conditioned_loss=loss,collections_episodes=history,collections_value=value,prior_known_cure_and_redefault=cure)
  if(verify_reference){stopifnot(abs(sum(vapply(Filter(function(r)r$claim_id%in%unlist(case$owned_claim_ids),allocation$claim_results),function(r)r$gross_recovery,numeric(1)))-case$terminal)<1e-8);expected<-ead-.99*case$past-.95*(case$terminal-case$cost);ratio<-(1+sqrt(.25*.75)*exp((log(3)/2)^2/2))/3;stopifnot(abs(closed$economic_loss-expected)<1e-8,is.null(incomplete$economic_lgd),is.null(unidentified$episodes[[1]]$expected_final_lgd),abs(estimated$episodes[[1]]$expected_final_loss-(ead-.99*case$past-.95*(ead-case$past)*ratio+.95*case$cost))<1e-6,abs(loss$expected_loss-.1*expected)<1e-8,abs(value[[1]]$expected_net_recovery-(.25*.95*(case$terminal-case$cost)+.75*.95*case$terminal/2-case$cost/10))<1e-8,identical(as.numeric(unlist(cure$sustained_cure_probability)),c(0,.5,.5)),identical(as.numeric(unlist(cure$cure_then_redefault_probability)),c(0,0,.5)),cure$expected_recovery==case$terminal/2,!cure$causal_effect_identified,identical(vapply(history$episodes,function(r)r$status,character(1)),c('CURED','OPEN')),all(vapply(history$episodes,function(r)r$ever_default,logical(1))))}
 }
 list(product=data$product,data_origin=data$data_origin,version=data$version,cure_training=list(calendar_origin=tr$calendar_origin,observation_end=tr$observation_end,known_at=tr$training$known_at,training_subjects=as.list(sort(unique(vapply(tr$rows,function(r)r$entity_id,character(1)))))),cases=out)
}
